$dir = 'app/Http/Controllers';
$models = ['GayaBelajar', 'Panas', 'Srq20', 'Swls'];

foreach($models as $model) {
    $content = "<?php\n\nnamespace App\Http\Controllers;\n\nuse App\Models\\$model;\nuse Illuminate\Http\Request;\nuse Inertia\Inertia;\n\nclass Admin{$model}Controller extends Controller\n{\n    public function index()\n    {\n        \$data = $model::latest()->paginate(15);\n        return Inertia::render('Admin/{$model}/Index', ['data' => \$data]);\n    }\n\n    public function destroy(\$id)\n    {\n        \$record = $model::findOrFail(\$id);\n        \$record->delete();\n        return redirect()->back()->with('success', 'Data berhasil dihapus');\n    }\n\n    public function export()\n    {\n        // TODO: Export implementation\n        return redirect()->back()->with('success', 'Export initiated');\n    }\n}\n";
